package com.fitnutri.backend.activity.catalogue;
import com.fitnutri.backend.activity.*;
import com.fitnutri.backend.common.BusinessException;
import java.math.BigDecimal;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.core.io.*;
import static org.junit.jupiter.api.Assertions.*;
class ExerciseOptionImporterTest {
 final tools.jackson.databind.ObjectMapper json=new tools.jackson.databind.ObjectMapper();final ExerciseOptionCatalogueReader reader=new ExerciseOptionCatalogueReader(json);
 ExerciseOptionCatalogueReader.Bundle document(){return reader.prepare(new ClassPathResource("data/ux/exercise-options-v1.json"),new ClassPathResource("data/ux/movement-catalogue-v1.json"));}
 @Test void reviewedCoverageKeepsMovementEnergySeparateAndAllDefaultsStrength(){var data=document();assertEquals(38,data.options().entries().size());assertEquals(36,data.movements().entries().size());assertTrue(data.movements().entries().stream().allMatch(m->m.defaultOptionKey().equals("strength-general")));var rower=data.options().entries().stream().filter(r->r.optionKey().equals("rowing-machine")).findFirst().orElseThrow();assertEquals("UNAVAILABLE",rower.mappingKind());assertNull(rower.activityKey());assertTrue(data.movements().entries().stream().anyMatch(m->m.aliases().contains("划船")&&m.displayName().contains("strength")));}
 @Test void onlyExactActiveVerifiedSourceRevisionCodeAndDescriptionMayMap(){var doc=document();var option=doc.options().entries().stream().filter(r->r.optionKey().equals("rowing-under100w")).findFirst().orElseThrow();var dataset=new ActivityDataset();dataset.setId(1L);dataset.setName(doc.options().dataset().name());dataset.setRelease(doc.options().dataset().release());dataset.setRevision(doc.options().dataset().revision());dataset.setContentSha256(doc.options().dataset().recordsSha256());dataset.setMinAge(19);dataset.setMaxAge(59);dataset.setVerified(true);var row=new ExerciseType();row.setId(101L);row.setDataset(dataset);row.setActivityKey(option.activityKey());row.setSourceActivityCode(option.sourceActivityCode());row.setSourceDescription(option.sourceDescription());row.setMetValue(new BigDecimal("5.0"));row.setActive(true);assertDoesNotThrow(()->reader.validateOptionMapping(doc.options().dataset(),option,row));row.setSourceDescription("Invented generic rower");assertThrows(BusinessException.class,()->reader.validateOptionMapping(doc.options().dataset(),option,row));row.setSourceDescription(option.sourceDescription());row.setActive(false);assertThrows(BusinessException.class,()->reader.validateOptionMapping(doc.options().dataset(),option,row));row.setActive(true);dataset.setRevision("other");assertThrows(BusinessException.class,()->reader.validateOptionMapping(doc.options().dataset(),option,row));assertThrows(BusinessException.class,()->reader.validateOptionMapping(doc.options().dataset(),option,null));}
 @Test void changedUnreviewedOrExtraAuthorityArtifactCannotActivate()throws Exception{var resource=new ClassPathResource("data/ux/exercise-options-v1.json");String original=new String(resource.getInputStream().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);for(String changed:List.of(original.replace("REVIEWED","DRAFT"),original.replace("\"entries\": [","\"metValue\": 999, \"entries\": ["),original+" "))assertThrows(BusinessException.class,()->reader.prepare(new ByteArrayResource(changed.getBytes(java.nio.charset.StandardCharsets.UTF_8)),new ClassPathResource("data/ux/movement-catalogue-v1.json")));}
 @Test void unavailableChoiceNeverBorrowsAReference(){var doc=document();var unavailable=doc.options().entries().stream().filter(r->r.optionKey().equals("rowing-machine")).findFirst().orElseThrow();assertDoesNotThrow(()->reader.validateOptionMapping(doc.options().dataset(),unavailable,null));assertThrows(BusinessException.class,()->reader.validateOptionMapping(doc.options().dataset(),unavailable,new ExerciseType()));}
}
